// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI, System.Text.Json

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.Text.Json;
using System.ComponentModel;

public class ConversationTurn
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public DateTimeOffset Timestamp { get; set; } = DateTimeOffset.UtcNow;
}

public class ConversationMemory
{
    private readonly List<ConversationTurn> _turns = new();
    private readonly int _maxRecentTurns;
    private readonly int _tokenBudget;

    public ConversationMemory(int maxRecentTurns = 10, int tokenBudget = 2000)
    {
        _maxRecentTurns = maxRecentTurns;
        _tokenBudget = tokenBudget;
    }

    public async Task AddTurnAsync(string role, string content)
    {
        _turns.Add(new ConversationTurn
        {
            Role = role,
            Content = content,
            Timestamp = DateTimeOffset.UtcNow
        });

        await Task.CompletedTask;
    }

    public async Task<string> GetHistoryAsync()
    {
        var recent = _turns.Skip(Math.Max(0, _turns.Count - _maxRecentTurns));
        var history = string.Join("\n", recent.Select(t => $"{t.Role}: {t.Content}"));
        return await Task.FromResult(history);
    }

    public async Task<string> GetSummarizedHistoryAsync(Kernel summaryKernel)
    {
        var recent = _turns.Skip(Math.Max(0, _turns.Count - _maxRecentTurns));
        var recentText = string.Join("\n", recent.Select(t => $"{t.Role}: {t.Content}"));

        if (recentText.Length > _tokenBudget && summaryKernel != null)
        {
            // Summarize older turns to fit within token budget
            var arguments = new KernelArguments();
            arguments["input"] = recentText;

            var summary = await summaryKernel.InvokePromptAsync<string>(
                "Summarize the following conversation in 2-3 sentences: {$$input}",
                arguments);
            return summary;
        }

        return await Task.FromResult(recentText);
    }

    public IReadOnlyList<ConversationTurn> GetAllTurns() => _turns.AsReadOnly();
}

